type FlagKey = 'newCheckout' | 'darkMode' | 'betaSearch';
type FlagConfig = Record<FlagKey, { enabled: boolean; rollout: number }>;

// the shared config
const flags = {
  newCheckout: { enabled: true, rollout: 50 },
  darkMode: { enabled: true, rollout: 100 },
} as FlagConfig;

// consumers
function rolloutFor(key: FlagKey) {
  return flags[key].rollout; // typed number, always defined
}

